    for i in range(H):
        for j in range(W):
            if not seen[i][j] and inp[i][j]!=bg:
                v=inp[i][j]; st=[(i,j)]; seen[i][j]=True; comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and inp[x][y]==v:
                            seen[x][y]=True; st.append((x,y))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                sub=[row[c0:c1+1] for row in inp[r0:r1+1]]
                # valid frame: border all v? check demo: frame value = v (6), interior may contain another color (1)
                if all(v==sub[k][kk] or kk not in (c1-c0-1,) and k not in (0,len(sub)-1) for kk,kk in [(0,i),(c1-c0,i) for i in range(len(sub))] + [(i,0),(i,c1-c0) for i in range(len(sub))]):
                    # simpler: check border of sub == v
                    okb=all(sub[k][0]==v and sub[k][-1]==v for k in range(len(sub))) and \
                         all(sub[0][jj]==v and sub[-1][jj]==v for jj in range(len(sub[0])))
                    inner=set()
                    for k in range(1,len(sub)-1):
                        for jj in range(1,len(sub[0])-1):
                            inner.add(sub[k][jj])
                    if len(inner)==1 and len(comp)>4:
                        col=list(inner)[0]
                        res=[[col]*(len(sub[0])) for _ in range(len(sub))]
                        return res
